# 180_FUNCTIONAL_REGIONAL_IDENTITY_STANDALONE.R
#
# Standalone reconstruction of functional persistence, prevalence and regional
# differentiation. The only scientific inputs are the original KO count matrix
# and the original metadata table. No RUN*, LATEST*, RDS classification or
# table generated by another analysis script is read.
#
# This script deliberately treats two KO classifications as independent axes:
#   1) persistence class: absolute core / near-global / realm-core / periphery
#   2) global prevalence: Prevalent / Shell / Cloud
#
# It starts from every metagenome in the assembly-quality-filtered KO matrix
# and validates the retained accession manifest against corrected metadata.
# Three air controls are excluded explicitly. No cohort downsampling is applied.
#
# The final four panels are:
#   a) cross-tabulation of persistence and prevalence definitions;
#   b) regional R2 for their biologically interpretable intersections;
#   c) balanced R2 distributions for Prevalent, Shell and Cloud KOs;
#   d) paired Shell advantage under design and sensitivity analyses.
#
# Canonical key: run_accession.
# Functional potential only; not expression, activity or metabolic flux.

get_arg <- function(flag, default = NULL) {
  args <- commandArgs(trailingOnly = TRUE)
  hit <- which(args == flag)
  if (length(hit) == 0L || hit[length(hit)] == length(args)) return(default)
  args[hit[length(hit)] + 1L]
}

as_int <- function(x, label) {
  y <- suppressWarnings(as.integer(x))
  if (length(y) != 1L || is.na(y)) stop(label, " must be an integer.")
  y
}

as_num <- function(x, label) {
  y <- suppressWarnings(as.numeric(x))
  if (length(y) != 1L || is.na(y)) stop(label, " must be numeric.")
  y
}

as_flag <- function(x, label) {
  y <- tolower(trimws(as.character(x)))
  if (y %in% c("1", "true", "yes", "y")) return(TRUE)
  if (y %in% c("0", "false", "no", "n")) return(FALSE)
  stop(label, " must be 0/1 or false/true.")
}

