close_logging <- function() {
  # With no message diversion, sink.number(type = "message") returns 2
  # (stderr), not 0. Testing > 0 therefore creates an infinite loop.
  while (sink.number(type = "message") != 2L) sink(type = "message")
  while (sink.number(type = "output") > 0L) sink(type = "output")
  if (isOpen(log_con)) close(log_con)
  invisible(TRUE)
}

log_msg <- function(...) {
  cat(sprintf("[%s] ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")), ..., "\n", sep = "")
}

options(error = function() {
  error_text <- geterrmessage()
  try(
    cat(
      sprintf("[%s] FATAL: %s\n", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), error_text),
      file = LOG_FILE,
      append = TRUE
    ),
    silent = TRUE
  )
  try(
    writeLines(
      c(
        "FAIL",
        paste0("timestamp_utc=", format(Sys.time(), "%Y-%m-%d %H:%M:%S UTC", tz = "UTC")),
        paste0("error=", gsub("[\r\n]+", " ", error_text))
      ),
      STATUS_FILE
    ),
    silent = TRUE
  )
  try(close_logging(), silent = TRUE)
  options(error = NULL)
  quit(save = "no", status = 1L, runLast = FALSE)
})

write_tsv <- function(x, path) {
  if (is.null(x) || (is.data.frame(x) && ncol(x) == 0L)) {
    writeLines(character(), path)
    return(invisible(path))
  }
  utils::write.table(
    x,
    file = path,
    sep = "\t",
    quote = FALSE,
    row.names = FALSE,
    col.names = TRUE,
    na = ""
  )
}

sha256_file <- function(path) {
  output <- suppressWarnings(
    system2("sha256sum", args = path, stdout = TRUE, stderr = TRUE)
  )
  status <- attr(output, "status")
  if (!is.null(status) && status != 0L) return(NA_character_)
  if (length(output) != 1L) return(NA_character_)
  token <- strsplit(output, "[[:space:]]+")[[1L]][1L]
  if (!grepl("^[0-9a-f]{64}$", token)) return(NA_character_)
  token
}

build_input_manifest <- function(paths) {
  info <- file.info(paths)
  data.frame(
    role = c("metadata", "KO_count_matrix", "analysis_script", "accession_manifest", "atlas_classification_reference")[seq_along(paths)],
    file = normalizePath(paths, winslash = "/", mustWork = TRUE),
    size_bytes = info$size,
    modified_utc = format(info$mtime, "%Y-%m-%d %H:%M:%S UTC", tz = "UTC"),
    md5 = unname(tools::md5sum(paths)),
    sha256 = vapply(paths, sha256_file, character(1)),
    stringsAsFactors = FALSE
  )
}

clean_chr <- function(x) {
  y <- trimws(as.character(x))
  missing <- is.na(y) | y == "" | tolower(y) %in% c("na", "n/a", "nan", "null", "none")
  y[missing] <- NA_character_
  y
}

norm_id <- function(x) {
  y <- tolower(trimws(as.character(x)))
  y <- gsub("[^a-z0-9]+", "_", y)
  gsub("^_+|_+$", "", y)
}

find_col <- function(df, candidates, required = TRUE, label = "column") {
  nms <- names(df)
  hit <- which(norm_id(nms) %in% norm_id(candidates))
  if (length(hit) == 0L) {
    if (required) stop("Could not resolve ", label, ". Candidates: ", paste(candidates, collapse = ", "))
    return(NA_character_)
  }
  nms[hit[1L]]
}

read_table_auto <- function(path) {
  if (!file.exists(path)) stop("File does not exist: ", path)
  if (requireNamespace("data.table", quietly = TRUE)) {
    return(as.data.frame(data.table::fread(path, data.table = FALSE, check.names = FALSE)))
  }
  is_gz <- grepl("\\.gz$", path, ignore.case = TRUE)
  first_con <- if (is_gz) gzfile(path, "rt") else file(path, "rt")
  first <- readLines(first_con, n = 1L, warn = FALSE)
  close(first_con)
  sep <- if (grepl("\t", first, fixed = TRUE)) "\t" else ","
  con <- if (is_gz) gzfile(path, "rt") else file(path, "rt")
  on.exit(close(con), add = TRUE)
  utils::read.table(
    con,
    sep = sep,
    header = TRUE,
    quote = "",
    comment.char = "",
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
}

first_non_missing <- function(x) {
  y <- clean_chr(x)
  y <- y[!is.na(y)]
  if (length(y) == 0L) NA_character_ else y[1L]
}

collapse_metadata <- function(df, run_col, fields) {
  ids <- clean_chr(df[[run_col]])
  df <- df[!is.na(ids), , drop = FALSE]
  ids <- ids[!is.na(ids)]
  split_idx <- split(seq_len(nrow(df)), clean_chr(df[[run_col]]))
  out <- lapply(names(split_idx), function(id) {
    idx <- split_idx[[id]]
    row <- data.frame(run_accession = id, stringsAsFactors = FALSE)
    for (nm in names(fields)) {
      col <- fields[[nm]]
      row[[nm]] <- if (is.na(col)) NA_character_ else first_non_missing(df[[col]][idx])
    }
    row
  })
  out <- do.call(rbind, out)

  audit <- lapply(names(split_idx), function(id) {
    idx <- split_idx[[id]]
    do.call(rbind, lapply(names(fields), function(nm) {
      col <- fields[[nm]]
      if (is.na(col)) return(NULL)
      vals <- unique(clean_chr(df[[col]][idx]))
      vals <- vals[!is.na(vals)]
      if (length(vals) <= 1L) return(NULL)
      data.frame(
        run_accession = id,
        field = nm,
        values = paste(vals, collapse = " | "),
        stringsAsFactors = FALSE
      )
    }))
  })
  audit <- do.call(rbind, audit)
  if (is.null(audit)) {
    audit <- data.frame(run_accession = character(), field = character(), values = character())
  }
  list(metadata = out, audit = audit)
}

numeric_matrix_from_df <- function(df) {
  m <- as.matrix(data.frame(lapply(df, function(x) suppressWarnings(as.numeric(as.character(x)))), check.names = FALSE))
  if (any(!is.finite(m)) || any(m < 0)) stop("KO counts must be finite and non-negative; no missing-value imputation is allowed.")
  storage.mode(m) <- "numeric"
  m
}

match_ids <- function(query, reference) {
  out <- rep(NA_character_, length(query))
  direct <- match(query, reference)
  hit <- !is.na(direct)
  out[hit] <- reference[direct[hit]]
  remaining <- is.na(out)
  ci <- match(tolower(query[remaining]), tolower(reference))
  idx <- which(remaining)
  out[idx[!is.na(ci)]] <- reference[ci[!is.na(ci)]]
  remaining <- is.na(out)
  relaxed <- match(norm_id(query[remaining]), norm_id(reference))
  idx <- which(remaining)
  out[idx[!is.na(relaxed)]] <- reference[relaxed[!is.na(relaxed)]]
  out
}

load_ko_matrix <- function(path, metadata_ids) {
  raw <- read_table_auto(path)
  ko_counts <- vapply(raw, function(x) sum(grepl("^K[0-9]{5}$", clean_chr(x))), integer(1))
  ko_col <- names(ko_counts)[which.max(ko_counts)]

  if (max(ko_counts) >= 10L) {
    ko <- clean_chr(raw[[ko_col]])
    keep <- grepl("^K[0-9]{5}$", ko)
    raw <- raw[keep, , drop = FALSE]
    ko <- ko[keep]
    matrix_ids <- setdiff(names(raw), ko_col)
    matched_all <- match_ids(matrix_ids, metadata_ids)
    unmatched_matrix_ids <- matrix_ids[is.na(matched_all)]
    candidate_cols <- matrix_ids
    matched <- matched_all
    keep_cols <- !is.na(matched)
    if (!any(keep_cols)) stop("No KO-matrix columns matched metadata run_accession.")
    candidate_cols <- candidate_cols[keep_cols]
    matched <- matched[keep_cols]
    if (anyDuplicated(matched)) {
      stop("Multiple KO-matrix columns map to the same run_accession.")
    }
    mat <- numeric_matrix_from_df(raw[, candidate_cols, drop = FALSE])
    colnames(mat) <- matched
    if (anyDuplicated(ko)) stop("Duplicated KO identifiers in the count matrix.")
    rownames(mat) <- ko
    matching <- data.frame(
      matrix_id = matrix_ids,
      run_accession = matched_all,
      matched = !is.na(matched_all),
      orientation = "KOs_by_samples",
      stringsAsFactors = FALSE
    )
    return(list(
      mat = mat,
      matching = matching,
      matrix_sample_ids = matrix_ids,
      unmatched_matrix_ids = unmatched_matrix_ids,
      orientation = "KOs_by_samples"
    ))
  }

  ko_cols <- names(raw)[grepl("^K[0-9]{5}$", names(raw))]
  if (length(ko_cols) < 10L) stop("Could not detect KOs in rows or columns.")
  match_counts <- vapply(raw, function(x) sum(!is.na(match_ids(clean_chr(x), metadata_ids))), integer(1))
  sample_col <- names(match_counts)[which.max(match_counts)]
  sample_ids <- clean_chr(raw[[sample_col]])
  matched_all <- match_ids(sample_ids, metadata_ids)
  unmatched_matrix_ids <- sample_ids[is.na(matched_all)]
  matched <- matched_all
  keep <- !is.na(matched)
  if (!any(keep)) stop("No KO-matrix rows matched metadata run_accession.")
  raw <- raw[keep, , drop = FALSE]
  matched <- matched[keep]
  if (anyDuplicated(matched)) {
    stop("Multiple KO-matrix rows map to the same run_accession.")
  }
  mat <- t(numeric_matrix_from_df(raw[, ko_cols, drop = FALSE]))
  colnames(mat) <- matched
  rownames(mat) <- ko_cols
  matching <- data.frame(
    matrix_id = sample_ids,
    run_accession = matched_all,
    matched = !is.na(matched_all),
    orientation = "samples_by_KOs",
    stringsAsFactors = FALSE
  )
  list(
    mat = mat,
    matching = matching,
    matrix_sample_ids = sample_ids,
    unmatched_matrix_ids = unmatched_matrix_ids,
    orientation = "samples_by_KOs"
  )
}

parse_threshold_pairs <- function(x) {
  pieces <- strsplit(x, ",", fixed = TRUE)[[1L]]
  out <- lapply(pieces, function(z) {
    vals <- suppressWarnings(as.numeric(strsplit(trimws(z), ":", fixed = TRUE)[[1L]]))
    if (length(vals) != 2L || anyNA(vals)) stop("Invalid threshold pair: ", z)
    if (!(vals[1L] > vals[2L] && vals[1L] <= 1 && vals[2L] >= 0)) {
      stop("Threshold pair must be prevalent:cloud with prevalent > cloud: ", z)
    }
    data.frame(prevalent = vals[1L], cloud = vals[2L])
  })
  unique(do.call(rbind, out))
}

parse_csv_values <- function(x, label) {
  out <- trimws(strsplit(as.character(x), ",", fixed = TRUE)[[1L]])
  out <- unique(out[nzchar(out)])
  if (length(out) == 0L) stop(label, " must contain at least one value.")
  out
}

parse_integer_values <- function(x, label) {
  raw <- parse_csv_values(x, label)
  out <- suppressWarnings(as.integer(raw))
  if (anyNA(out) || any(out < 1L)) stop(label, " must contain positive integers.")
  unique(out)
}

clr_by_features <- function(mat, kos, pseudocount = 1) {
  kos <- intersect(kos, rownames(mat))
  if (length(kos) < 2L) return(NULL)
  x <- t(mat[kos, , drop = FALSE])
  lx <- log(x + pseudocount)
  sweep(lx, 1L, rowMeans(lx), "-")
}

permanova_stats_fast <- function(x, realm) {
  ok <- !is.na(realm)
  x <- x[ok, , drop = FALSE]
  realm <- droplevels(factor(realm[ok]))
  n <- nrow(x)
  p <- nlevels(realm)
  if (n < 4L || p < 2L || n <= p || ncol(x) < 2L) {
    return(c(R2 = NA_real_, F = NA_real_, df_model = NA_real_, df_residual = NA_real_))
  }
  d2 <- as.matrix(stats::dist(x))^2
  g <- -0.5 * (d2 - rowMeans(d2) - rep(colMeans(d2), each = n) + mean(d2))
  X <- stats::model.matrix(~ realm)
  H <- X %*% qr.solve(crossprod(X), t(X))
  ss_total <- sum(diag(g))
  ss_model <- sum(diag(H %*% g))
  ss_res <- ss_total - ss_model
  df_model <- p - 1L
  df_res <- n - p
  if (!is.finite(ss_total) || ss_total <= 0 || ss_res <= 0) {
    return(c(R2 = NA_real_, F = NA_real_, df_model = df_model, df_residual = df_res))
  }
  c(
    R2 = ss_model / ss_total,
    F = (ss_model / df_model) / (ss_res / df_res),
    df_model = df_model,
    df_residual = df_res
  )
}

resolve_fixed_realms <- function(meta, requested, expected_n, n_localities, label) {
  requested <- parse_csv_values(requested, paste0(label, " realms"))
  if (length(requested) != expected_n) {
    stop(label, " design requires exactly ", expected_n, " realms; received ", length(requested), ".")
  }
  available <- unique(meta$realm)
  matched <- match_ids(requested, available)
  if (anyNA(matched)) {
    stop(
      label, " design contains realms absent from metadata: ",
      paste(requested[is.na(matched)], collapse = " | ")
    )
  }
  matched <- unique(matched)
  if (length(matched) != expected_n) stop(label, " realm names are not unique after normalization.")
  units <- unique(meta[meta$realm %in% matched, c("realm", "realm_locality")])
  counts <- table(factor(units$realm, levels = matched))
  if (any(counts < n_localities)) {
    bad <- paste0(names(counts)[counts < n_localities], " (", counts[counts < n_localities], ")")
    stop(
      label, " design is not estimable: fewer than ", n_localities,
      " localities in ", paste(bad, collapse = " | "), "."
    )
  }
  matched
}

design_is_estimable <- function(meta, realms, n_localities) {
  units <- unique(meta[meta$realm %in% realms, c("realm", "realm_locality")])
  counts <- table(factor(units$realm, levels = realms))
  all(counts >= n_localities)
}

sample_balanced_ids <- function(meta, realms, n_localities) {
  selected <- character()
  for (r in realms) {
    units <- unique(meta$realm_locality[meta$realm == r])
    if (length(units) < n_localities) return(NULL)
    chosen_units <- sample(units, n_localities, replace = FALSE)
    for (u in chosen_units) {
      ids <- meta$run_accession[meta$realm == r & meta$realm_locality == u]
      selected <- c(selected, sample(ids, 1L))
    }
  }
  selected
}

.DIST_CACHE <- list()
cached_distance <- function(x) {
  # Every CLR matrix derives from the same immutable input cohort and pseudocount.
  hit <- which(vapply(.DIST_CACHE, function(z) {
    identical(z$features, colnames(x)) && identical(z$samples, rownames(x))
  }, logical(1)))
  if (length(hit)) return(.DIST_CACHE[[hit[1L]]]$distance)
  d <- as.matrix(stats::dist(x))
  .DIST_CACHE[[length(.DIST_CACHE)+1L]] <<- list(
    features=colnames(x), samples=rownames(x), distance=d)
  d
}

run_balanced_groups <- function(
    clr_list,
    meta,
    realms,
    n_localities,
    n_iter,
    seed,
    design_label,
    diagnostic_iterations = 0L,
    nperm = 0L) {
  if (!design_is_estimable(meta, realms, n_localities)) return(data.frame())
  diagnostic_iterations <- min(as.integer(diagnostic_iterations), n_iter)
  diagnostic_schedule <- if (diagnostic_iterations > 0L && nperm > 0L) {
    unique(as.integer(round(seq(1, n_iter, length.out = diagnostic_iterations))))
  } else {
    integer()
  }
  distance_cache <- lapply(clr_list, cached_distance)
  out <- vector("list", n_iter * length(clr_list))
  k <- 0L
  for (i in seq_len(n_iter)) {
    if (i==1L || i %% 50L == 0L) log_msg(design_label, ": ", i, "/", n_iter)
    set.seed(seed + i)
    ids <- sample_balanced_ids(meta, realms, n_localities)
    if (is.null(ids)) next
    m <- meta[match(ids, meta$run_accession), , drop = FALSE]
    for (j in seq_along(clr_list)) {
      nm <- names(clr_list)[j]
      n_features <- ncol(clr_list[[nm]])
      d <- stats::as.dist(distance_cache[[nm]][ids, ids, drop=FALSE])
      d2 <- as.matrix(d)^2
      gram <- -0.5 * (d2 - rowMeans(d2) - rep(colMeans(d2), each=nrow(d2)) + mean(d2))
      design_base <- cbind(1, m$log10_KO_total)
      design_full <- model.matrix(~ log10_KO_total + realm, m)
      q0 <- qr.Q(qr(design_base)); q1 <- qr.Q(qr(design_full))
      ss_total <- sum(diag(gram))
      ss0 <- sum(diag(crossprod(q0, gram %*% q0)))
      ss1 <- sum(diag(crossprod(q1, gram %*% q1)))
      unique_R2 <- max(0, (ss1-ss0)/ss_total)
      partial_R2 <- max(0, (ss1-ss0)/(ss_total-ss0))
      q_realm <- qr.Q(qr(model.matrix(~ realm, m)))
      ss_realm <- sum(diag(crossprod(q_realm, gram %*% q_realm)))
      df_realm <- length(unique(m$realm))-1L
      df_residual <- nrow(m)-length(unique(m$realm))
      st <- c(R2=ss_realm/ss_total, F=(ss_realm/df_realm)/((ss_total-ss_realm)/df_residual))
      permanova_P <- adjusted_P <- permdisp_F <- permdisp_P <- NA_real_
      diagnostic_error <- NA_character_
      if (i %in% diagnostic_schedule) {
        diagnostic <- tryCatch({
          dat <- data.frame(realm = droplevels(factor(m$realm)), log10_KO_total = m$log10_KO_total)
          set.seed(seed + 1000000L + i * 100L + j)
          ad <- vegan::adonis2(d ~ realm, data = dat, permutations = nperm)
          set.seed(seed + 1000000L + i * 100L + j)
          adj <- vegan::adonis2(d ~ log10_KO_total + realm, data=dat, permutations=nperm, by="margin")
          if (abs(adj$R2[which(rownames(adj)=="realm")]-unique_R2)>1e-8) stop("Adjusted R2 independent check failed.")
          bd <- vegan::betadisper(
            d,
            dat$realm,
            type = "median",
            bias.adjust = TRUE
          )
          if (any(!is.finite(bd$distances))) {
            stop("Balanced PERMDISP produced non-finite distances.")
          }
          set.seed(seed + 2000000L + i * 100L + j)
          pd <- vegan::permutest(
            bd,
            permutations = nperm,
            parallel = 1L
          )
          c(
            permanova_P = ad$`Pr(>F)`[1L],
            adjusted_P = adj$`Pr(>F)`[which(rownames(adj)=="realm")],
            permdisp_F = pd$tab[1L, "F"],
            permdisp_P = pd$tab[1L, "Pr(>F)"]
          )
        }, error = function(e) e)
        if (inherits(diagnostic, "error")) {
          diagnostic_error <- conditionMessage(diagnostic)
        } else {
          permanova_P <- unname(diagnostic["permanova_P"])
          adjusted_P <- unname(diagnostic["adjusted_P"])
          permdisp_F <- unname(diagnostic["permdisp_F"])
          permdisp_P <- unname(diagnostic["permdisp_P"])
        }
      }
      k <- k + 1L
      out[[k]] <- data.frame(
        design = design_label,
        iteration = i,
        group = nm,
        n_samples = length(ids),
        n_KOs = n_features,
        R2 = unname(st["R2"]),
        F = unname(st["F"]),
        adjusted_unique_R2 = unique_R2,
        adjusted_partial_R2 = partial_R2,
        adjusted_P = adjusted_P,
        diagnostic_iteration = i %in% diagnostic_schedule,
        permanova_P = permanova_P,
        permdisp_F = permdisp_F,
        permdisp_P = permdisp_P,
        diagnostic_error = diagnostic_error,
        selected_run_accessions = paste(ids, collapse = ";"),
        stringsAsFactors = FALSE
      )
    }
  }
  out <- out[seq_len(k)]
  if (length(out) == 0L) return(data.frame())
  do.call(rbind, out)
}

summarize_balanced_diagnostics <- function(x) {
  if (nrow(x) == 0L) return(data.frame())
  keys <- interaction(x$design, x$group, drop = TRUE, lex.order = TRUE)
  parts <- split(x, keys)
  out <- lapply(parts, function(z) {
    r2 <- z$R2[is.finite(z$R2)]
    p_ad <- z$permanova_P[is.finite(z$permanova_P)]
    p_bd <- z$permdisp_P[is.finite(z$permdisp_P)]
    p_adj <- z$adjusted_P[is.finite(z$adjusted_P)]
    data.frame(
      design = z$design[1L],
      group = z$group[1L],
      n_KOs = z$n_KOs[1L],
      n_R2_iterations = length(r2),
      median_R2 = if (length(r2)) stats::median(r2) else NA_real_,
      q05_R2 = if (length(r2)) stats::quantile(r2, 0.05, names = FALSE) else NA_real_,
      q95_R2 = if (length(r2)) stats::quantile(r2, 0.95, names = FALSE) else NA_real_,
      median_adjusted_unique_R2 = median(z$adjusted_unique_R2),
      q05_adjusted_unique_R2 = quantile(z$adjusted_unique_R2, 0.05, names=FALSE),
      q95_adjusted_unique_R2 = quantile(z$adjusted_unique_R2, 0.95, names=FALSE),
      median_adjusted_partial_R2 = median(z$adjusted_partial_R2),
      fraction_adjusted_P_le_0.05 = if(length(p_adj)) mean(p_adj<=0.05) else NA_real_,
      n_diagnostic_iterations = length(p_ad),
      fraction_PERMANOVA_P_le_0.05 = if (length(p_ad)) mean(p_ad <= 0.05) else NA_real_,
      fraction_PERMDISP_P_le_0.05 = if (length(p_bd)) mean(p_bd <= 0.05) else NA_real_,
      n_diagnostic_errors = sum(!is.na(z$diagnostic_error)),
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, out)
}

paired_shell_delta <- function(long_df) {
  if (nrow(long_df) == 0L) return(data.frame())
  wide <- reshape(
    long_df[, c("design", "iteration", "group", "R2")],
    idvar = c("design", "iteration"),
    timevar = "group",
    direction = "wide"
  )
  required <- c("R2.Prevalent", "R2.Shell", "R2.Cloud")
  for (nm in required) if (!nm %in% names(wide)) wide[[nm]] <- NA_real_
  wide$delta_R2 <- wide$R2.Shell - pmax(wide$R2.Prevalent, wide$R2.Cloud, na.rm = TRUE)
  wide[, c("design", "iteration", "delta_R2")]
}

summarize_interval <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0L) return(c(median = NA_real_, lower = NA_real_, upper = NA_real_, n = 0))
  bounds <- if (length(x) < 4L) range(x) else stats::quantile(x, c(0.05, 0.95), names = FALSE)
  c(median = stats::median(x), lower = bounds[1L], upper = bounds[2L], n = length(x))
}

full_permanova_permdisp <- function(
    clr_list,
    meta,
    nperm,
    seed,
    min_permdisp_group_n = 2L) {
  out <- lapply(seq_along(clr_list), function(i) {
    nm <- names(clr_list)[i]
    x <- clr_list[[nm]][meta$run_accession, , drop = FALSE]
    realm_all <- droplevels(factor(meta$realm))

    if (anyNA(realm_all)) {
      stop("Full-cohort PERMANOVA contains missing realm assignments.")
    }
    if (any(!is.finite(x))) {
      stop(
        "Full-cohort CLR matrix contains non-finite values for group ",
        nm,
        "."
      )
    }

    realm_counts <- table(realm_all)
    eligible_realms <- names(realm_counts)[
      realm_counts >= min_permdisp_group_n
    ]
    excluded_realms <- names(realm_counts)[
      realm_counts < min_permdisp_group_n
    ]
    if (length(eligible_realms) < 2L) {
      stop(
        "Fewer than two realms satisfy min_permdisp_group_n for group ",
        nm,
        "."
      )
    }

    # The unbalanced full-cohort PERMANOVA is only a sensitivity analysis and
    # retains all samples, including any realm represented by one sample.
    d <- stats::dist(x)
    dat <- data.frame(
      realm = realm_all,
      row.names = meta$run_accession
    )
    set.seed(seed + i)
    ad <- vegan::adonis2(
      d ~ realm,
      data = dat,
      permutations = nperm
    )

    # Within-group dispersion is undefined for singleton realms. PERMDISP uses
    # only realms meeting the explicit minimum, while preserving all eligible
    # samples. The primary balanced designs remain unchanged.
    permdisp_keep <- realm_all %in% eligible_realms
    x_permdisp <- x[permdisp_keep, , drop = FALSE]
    realm_permdisp <- droplevels(realm_all[permdisp_keep])
    d_permdisp <- stats::dist(x_permdisp)
    bd <- vegan::betadisper(
      d_permdisp,
      realm_permdisp,
      type = "median",
      bias.adjust = TRUE
    )
    if (any(!is.finite(bd$distances))) {
      stop(
        "Full-cohort PERMDISP produced non-finite distances after excluding ",
        "undersized realms for group ",
        nm,
        "."
      )
    }
    set.seed(seed + 10000L + i)
    pd <- vegan::permutest(
      bd,
      permutations = nperm,
      parallel = 1L
    )

    data.frame(
      group = nm,
      n_samples = nrow(x),
      n_realms_PERMANOVA = nlevels(realm_all),
      n_KOs = ncol(x),
      permanova_F = ad$F[1L],
      permanova_R2 = ad$R2[1L],
      permanova_P = ad$`Pr(>F)`[1L],
      n_samples_PERMDISP = nrow(x_permdisp),
      n_realms_PERMDISP = nlevels(realm_permdisp),
      min_realm_n_PERMDISP = min(as.integer(table(realm_permdisp))),
      PERMDISP_excluded_realms = paste(excluded_realms, collapse = " | "),
      permdisp_F = pd$tab[1L, "F"],
      permdisp_P = pd$tab[1L, "Pr(>F)"],
      stringsAsFactors = FALSE
    )
  })
  do.call(rbind, out)
}

save_plot_pair <- function(plot, stem, width = 3.65, height = 3.25) {
  ggplot2::ggsave(file.path(PLOTS_DIR, paste0(stem, ".png")), plot, width = width, height = height, dpi = DPI, bg = "white")
  ggplot2::ggsave(file.path(PLOTS_DIR, paste0(stem, ".pdf")), plot, width = width, height = height, device = grDevices::pdf, useDingbats = FALSE, encoding = "WinAnsi", bg = "white")
  ggplot2::ggsave(
    file.path(PLOTS_DIR, paste0(stem, ".tiff")),
    plot,
    width = width,
    height = height,
    dpi = DPI,
    device = "tiff",
    compression = "lzw",
    bg = "white"
  )
}

theme_pub <- function(base_size = 9.5) {
  ggplot2::theme_classic(base_size = base_size) +
    ggplot2::theme(
      axis.title = ggplot2::element_text(size = base_size + 0.5, colour = "black"),
      axis.text = ggplot2::element_text(size = base_size, colour = "black"),
      strip.background = ggplot2::element_blank(),
      strip.text = ggplot2::element_text(size = base_size, face = "bold"),
      legend.title = ggplot2::element_blank(),
      legend.text = ggplot2::element_text(size = base_size - 0.5),
      plot.margin = ggplot2::margin(5, 8, 5, 5)
    )
}

if (!(PREVALENT_THRESHOLD > CLOUD_THRESHOLD && PREVALENT_THRESHOLD <= 1 && CLOUD_THRESHOLD >= 0)) {
  stop("Require prevalent_threshold > cloud_threshold, both within [0,1].")
}
if (PSEUDOCOUNT <= 0) stop("pseudocount must be > 0.")
if (MIN_PERMDISP_GROUP_N < 2L) {
  stop("min_permdisp_group_n must be at least 2.")
}
if (STRICT_CLASS_COUNTS && sum(c(
  EXPECTED_ABSOLUTE_KOS,
  EXPECTED_NEAR_GLOBAL_KOS,
  EXPECTED_REALM_CORE_KOS,
  EXPECTED_PERIPHERY_KOS
)) != EXPECTED_KOS) {
  stop(
    "Historical persistence-class counts do not sum to expected_kos while ",
    "strict_class_counts is enabled."
  )
}
if (!file.exists(METADATA_FILE)) stop("Metadata input does not exist: ", METADATA_FILE)
if (!file.exists(KO_MATRIX_FILE)) stop("KO matrix input does not exist: ", KO_MATRIX_FILE)
EXPECTED_EXCLUDED_RUN_ACCESSIONS <- sort(
  parse_csv_values(
    EXCLUDED_RUN_ACCESSIONS_ARG,
    "exclude_run_accessions"
  )
)

set.seed(SEED)
log_msg("Starting ", SCRIPT_BASENAME)
log_msg("Script version: ", SCRIPT_VERSION)
log_msg("Metadata: ", METADATA_FILE)
log_msg("KO matrix: ", KO_MATRIX_FILE)
log_msg("Output: ", OUTDIR)
log_msg("Standalone mode: no derived RUN inputs are permitted.")
log_msg(
  "The KO matrix contains ", EXPECTED_MATRIX_SAMPLES,
  " samples before the explicit metadata exclusions; no geographic downsampling is applied."
)

# -----------------------------------------------------------------------------
# 1. Metadata and KO matrix
# -----------------------------------------------------------------------------
metadata_raw <- read_table_auto(METADATA_FILE)
run_col <- find_col(metadata_raw, c(RUN_COL_ARG, "run_accession"), TRUE, "run_accession")
realm_col <- if (!is.na(REALM_COL_ARG)) REALM_COL_ARG else find_col(
  metadata_raw,
  c("REALM", "realm", "MarineRealm", "marine_realm", "marine realm"),
  TRUE,
  "marine realm"
)
locality_col <- if (!is.na(LOCALITY_COL_ARG)) LOCALITY_COL_ARG else find_col(
  metadata_raw,
  c("Locality", "locality", "LOCALITY", "site", "Site", "location"),
  TRUE,
  "locality"
)
country_col <- if (!is.na(COUNTRY_COL_ARG)) COUNTRY_COL_ARG else find_col(
  metadata_raw,
  c("country", "Country", "COUNTRY"),
  FALSE,
  "country"
)
study_primary_col <- if (!is.na(STUDY_COL_ARG)) STUDY_COL_ARG else find_col(
  metadata_raw,
  c("study_accession", "Study", "study"),
  FALSE,
  "study accession"
)
bioproject_col <- find_col(
  metadata_raw,
  c("BioProject", "bioproject", "project_accession"),
  FALSE,
  "BioProject"
)
metadata_raw$.study_block_reconciled <- if (!is.na(study_primary_col)) {
  clean_chr(metadata_raw[[study_primary_col]])
} else {
  rep(NA_character_, nrow(metadata_raw))
}
if (!is.na(bioproject_col)) {
  fallback <- clean_chr(metadata_raw[[bioproject_col]])
  missing_study <- is.na(metadata_raw$.study_block_reconciled)
  metadata_raw$.study_block_reconciled[missing_study] <- fallback[missing_study]
}
metadata_run_ids <- clean_chr(metadata_raw[[run_col]])
internal_tx <- is.na(metadata_raw$.study_block_reconciled) & metadata_run_ids == "TX1_3"
metadata_raw$.study_block_reconciled[internal_tx] <- "INTERNAL_TX1_3"
study_col <- ".study_block_reconciled"

collapsed <- collapse_metadata(
  metadata_raw,
  run_col,
  c(realm = realm_col, locality = locality_col, country = country_col, study_block = study_col)
)
meta <- collapsed$metadata
if (is.na(ACCESSIONS_FILE) || !file.exists(ACCESSIONS_FILE)) stop("Supply --accessions with the canonical functional cohort manifest.")
allowed_ids <- clean_chr(readLines(ACCESSIONS_FILE, warn = FALSE))
if (anyNA(allowed_ids) || anyDuplicated(allowed_ids)) stop("Invalid accession manifest.")
if (!all(allowed_ids %in% meta$run_accession)) stop("Canonical accessions missing from metadata.")
meta <- meta[match(allowed_ids, meta$run_accession), , drop = FALSE]
write_tsv(collapsed$audit, file.path(TABLES_DIR, "180_metadata_duplicate_audit.tsv"))
if (nrow(collapsed$audit) > 0L) {
  critical <- collapsed$audit$field %in% c("realm", "locality", "country", "study_block")
  if (any(critical)) stop("Discordant realm/locality values found for duplicated run_accession.")
  log_msg("WARNING: non-critical duplicate metadata conflicts were resolved using the first non-missing value.")
}

loaded <- load_ko_matrix(KO_MATRIX_FILE, meta$run_accession)
mat <- loaded$mat
write_tsv(loaded$matching, file.path(TABLES_DIR, "180_functional_sample_matching.tsv"))

matrix_sample_ids <- clean_chr(loaded$matrix_sample_ids)
if (anyNA(matrix_sample_ids)) {
  stop("The KO matrix contains an empty sample identifier.")
}
if (anyDuplicated(matrix_sample_ids)) {
  duplicated_ids <- unique(matrix_sample_ids[duplicated(matrix_sample_ids)])
  stop(
    "The KO matrix contains duplicated sample identifiers: ",
    paste(duplicated_ids, collapse = ", "),
    "."
  )
}
actual_excluded_run_accessions <- sort(
  unique(clean_chr(loaded$unmatched_matrix_ids))
)
actual_excluded_run_accessions <- actual_excluded_run_accessions[
  !is.na(actual_excluded_run_accessions)
]

exclusion_audit <- data.frame(
  run_accession = sort(unique(c(
    EXPECTED_EXCLUDED_RUN_ACCESSIONS,
    actual_excluded_run_accessions
  ))),
  stringsAsFactors = FALSE
)
exclusion_audit$expected_exclusion <-
  exclusion_audit$run_accession %in% EXPECTED_EXCLUDED_RUN_ACCESSIONS
exclusion_audit$absent_from_complete_metadata <-
  exclusion_audit$run_accession %in% actual_excluded_run_accessions
exclusion_audit$validated <- with(
  exclusion_audit,
  expected_exclusion == absent_from_complete_metadata
)
write_tsv(
  exclusion_audit,
  file.path(TABLES_DIR, "180_intentional_sample_exclusions.tsv")
)

if (STRICT_EXPECTED && length(matrix_sample_ids) != EXPECTED_MATRIX_SAMPLES) {
  stop(
    "Expected ", EXPECTED_MATRIX_SAMPLES,
    " sample columns in the KO matrix, found ",
    length(matrix_sample_ids), "."
  )
}

if (!identical(
  actual_excluded_run_accessions,
  EXPECTED_EXCLUDED_RUN_ACCESSIONS
)) {
  stop(
    "Unmatched KO-matrix IDs differ from the explicitly authorized exclusions. ",
    "Expected: ", paste(EXPECTED_EXCLUDED_RUN_ACCESSIONS, collapse = ", "),
    "; observed: ", paste(actual_excluded_run_accessions, collapse = ", "),
    "."
  )
}

log_msg(
  "Validated intentional exclusions: ",
  paste(actual_excluded_run_accessions, collapse = " | ")
)

mat <- mat[rowSums(mat > PRESENCE_THRESHOLD) > 0, , drop = FALSE]
sample_totals <- colSums(mat)
if (any(sample_totals <= 0)) stop("Functional matrix contains zero-sum samples.")

meta <- meta[match(colnames(mat), meta$run_accession), , drop = FALSE]
if (anyNA(meta$run_accession)) stop("Internal sample matching failure.")

missing_core_meta <- is.na(meta$realm) | is.na(meta$locality)
write_tsv(meta[missing_core_meta, , drop = FALSE], file.path(TABLES_DIR, "180_samples_missing_realm_or_locality.tsv"))
if (any(missing_core_meta)) {
  if (STRICT_METADATA) stop("Functional samples are missing realm or locality metadata.")
  mat <- mat[, !missing_core_meta, drop = FALSE]
  meta <- meta[!missing_core_meta, , drop = FALSE]
}

if (!setequal(colnames(mat), allowed_ids)) stop("Matrix cohort differs from canonical accession manifest.")
meta$log10_KO_total <- log10(sample_totals[meta$run_accession])
meta$realm_locality <- paste(meta$realm, meta$locality, sep = " || ")
rownames(meta) <- meta$run_accession
mat <- mat[, meta$run_accession, drop = FALSE]

if (STRICT_EXPECTED && ncol(mat) != EXPECTED_SAMPLES) {
  stop("Expected ", EXPECTED_SAMPLES, " functional samples, found ", ncol(mat), ".")
}
if (STRICT_EXPECTED && nrow(mat) != EXPECTED_KOS) {
  stop("Expected ", EXPECTED_KOS, " non-zero KOs, found ", nrow(mat), ".")
}

write_tsv(meta, file.path(TABLES_DIR, "180_metadata_aligned_by_run_accession.tsv"))
realm_locality_counts <- aggregate(realm_locality ~ realm, unique(meta[, c("realm", "realm_locality")]), length)
names(realm_locality_counts)[2L] <- "n_localities"
realm_locality_counts$qualifies_core <- realm_locality_counts$n_localities >= MIN_REALM_LOCALITIES
write_tsv(realm_locality_counts, file.path(TABLES_DIR, "180_realm_locality_counts.tsv"))

log_msg("Functional samples matched: ", ncol(mat))
log_msg("Non-zero KOs: ", nrow(mat))
log_msg("Realm-locality units: ", length(unique(meta$realm_locality)))
guadeloupe_flag <- grepl("guadeloupe", meta$country, ignore.case = TRUE) |
  grepl("guadeloupe", meta$locality, ignore.case = TRUE)
guadeloupe_flag[is.na(guadeloupe_flag)] <- FALSE
n_guadeloupe <- sum(guadeloupe_flag)
log_msg("Guadeloupe samples retained from the functional matrix: ", n_guadeloupe)

# -----------------------------------------------------------------------------
# 2. Reconciled KO master classification
# -----------------------------------------------------------------------------
sample_totals <- colSums(mat)
rel <- sweep(mat, 2L, sample_totals, "/")
present <- mat > PRESENCE_THRESHOLD
global_prevalence_n <- rowSums(present)
global_prevalence <- global_prevalence_n / ncol(mat)

qualifying_realms <- realm_locality_counts$realm[realm_locality_counts$qualifies_core]
realm_core_any <- setNames(rep(FALSE, nrow(mat)), rownames(mat))
realm_core_realms <- setNames(rep("", nrow(mat)), rownames(mat))
realm_details <- list()

for (r in qualifying_realms) {
  samples_r <- meta$run_accession[meta$realm == r]
  units_r <- unique(meta$realm_locality[meta$realm == r])
  locality_counts <- vapply(units_r, function(u) {
    ids <- meta$run_accession[meta$realm_locality == u]
    rowSums(mat[, ids, drop = FALSE])
  }, numeric(nrow(mat)))
  if (is.null(dim(locality_counts))) {
    locality_counts <- matrix(locality_counts, ncol = 1L)
  }
  rownames(locality_counts) <- rownames(mat)
  colnames(locality_counts) <- units_r
  locality_totals <- colSums(locality_counts)
  if (any(locality_totals <= 0)) stop("Zero-sum realm-locality unit in ", r, ".")
  locality_relative <- sweep(locality_counts, 2L, locality_totals, "/")
  loc_presence <- locality_counts > PRESENCE_THRESHOLD
  present_all <- rowSums(loc_presence) == length(units_r)
  mean_rel_realm <- rowMeans(locality_relative)
  core_r <- present_all & mean_rel_realm >= MIN_MEAN_REL_REALM
  realm_core_any <- realm_core_any | core_r
  hits <- names(core_r)[core_r]
  realm_core_realms[hits] <- ifelse(
    realm_core_realms[hits] == "",
    r,
    paste(realm_core_realms[hits], r, sep = ";")
  )
  realm_details[[r]] <- data.frame(
    KO = rownames(mat),
    realm = r,
    n_samples = length(samples_r),
    n_localities = length(units_r),
    locality_weighting = "equal after summing replicate counts",
    present_all_localities = present_all,
