# Equal-KO resampling: all three prevalence groups use the same number of KOs.
ko_by_prev <- split(master$KO, master$prevalence_class)
equal_k <- min(vapply(ko_by_prev[prevalence_levels], length, integer(1)))
set.seed(SEED + 50L)
equal_out <- vector("list", N_EQUAL_KO_ITER * length(prevalence_levels))
k <- 0L
for (i in seq_len(N_EQUAL_KO_ITER)) {
  ids <- sample_balanced_ids(meta, primary_realms, PRIMARY_N_LOCALITIES)
  m <- meta[match(ids, meta$run_accession), , drop = FALSE]
  for (g in prevalence_levels) {
    sampled_kos <- sample(ko_by_prev[[g]], equal_k, replace = FALSE)
    x <- clr_by_features(mat, sampled_kos, PSEUDOCOUNT)[ids, , drop = FALSE]
    st <- permanova_stats_fast(x, m$realm)
    k <- k + 1L
    equal_out[[k]] <- data.frame(
      design = "Equal-KO resampling",
      iteration = i,
      group = g,
      n_samples = length(ids),
      n_KOs = equal_k,
      R2 = unname(st["R2"]),
      F = unname(st["F"]),
      stringsAsFactors = FALSE
    )
  }
}
equal_out <- do.call(rbind, equal_out)
write_tsv(equal_out, file.path(TABLES_DIR, "180_equal_KO_resampling_R2.tsv"))
delta_equal <- paired_shell_delta(equal_out)
delta_equal$analysis <- "Equal-KO resampling"
robust_raw[["equal"]] <- delta_equal

# Minimum-occurrence sensitivity. Prevalence classes remain defined from the
# complete post-exclusion cohort; only KOs below the requested occurrence count
# are removed before distance calculation.
occurrence_thresholds <- parse_integer_values(
  MIN_OCCURRENCE_SENSITIVITY,
  "min_occurrence_sensitivity"
)
occurrence_results <- list()
for (i in seq_along(occurrence_thresholds)) {
  min_occ <- occurrence_thresholds[i]
  if (min_occ <= 1L) next
  occ_clr <- setNames(lapply(prevalence_levels, function(g) {
    keep_kos <- master$KO[
      master$prevalence_class == g & master$global_prevalence_n >= min_occ
    ]
    clr_by_features(mat, keep_kos, PSEUDOCOUNT)
  }), prevalence_levels)
  if (any(vapply(occ_clr, is.null, logical(1)))) next
  rr <- run_balanced_groups(
    occ_clr,
    meta,
    primary_realms,
    PRIMARY_N_LOCALITIES,
    N_SENSITIVITY_ITER,
    SEED + 500L + i,
    paste0("Minimum occurrence >= ", min_occ)
  )
  dd <- paired_shell_delta(rr)
  dd$analysis <- paste0("Detected in >= ", min_occ, " samples")
  occurrence_results[[length(occurrence_results) + 1L]] <- rr
  robust_raw[[paste0("occurrence_", min_occ)]] <- dd
}
occurrence_results <- if (length(occurrence_results)) {
  do.call(rbind, occurrence_results)
} else {
  data.frame()
}
write_tsv(
