)

run_leaveout <- function(field, label, seed_offset) {
  if (!field %in% names(meta) || all(is.na(meta[[field]]))) {
    return(data.frame(
      analysis = character(),
      excluded = character(),
      delta_R2 = numeric(),
      n_iterations = integer(),
      stringsAsFactors = FALSE
    ))
  }
  active_meta <- meta[meta$realm %in% primary_realms, , drop=FALSE]
  blocks <- sort(unique(active_meta[[field]][!is.na(active_meta[[field]])]))
  results <- list()
  raw_results <- list()
  skipped <- list()
  for (i in seq_along(blocks)) {
    b <- blocks[i]
    msub <- meta[is.na(meta[[field]]) | meta[[field]] != b, , drop = FALSE]
    if (!design_is_estimable(msub, primary_realms, PRIMARY_N_LOCALITIES)) {
      skipped[[length(skipped) + 1L]] <- data.frame(analysis = label, excluded = b, reason = "fixed design not estimable")
      next
    }
    rr <- run_balanced_groups(
      prevalence_clr,
      msub,
      primary_realms,
      PRIMARY_N_LOCALITIES,
      N_SENSITIVITY_ITER,
      SEED + seed_offset + i,
      label
    )
    dd <- paired_shell_delta(rr)
    if (nrow(dd) > 0L) {
      dd$analysis <- label
      dd$excluded <- b
      raw_results[[length(raw_results) + 1L]] <- dd
      results[[length(results) + 1L]] <- data.frame(
        analysis = label,
        excluded = b,
        delta_R2 = stats::median(dd$delta_R2, na.rm = TRUE),
        n_iterations = sum(is.finite(dd$delta_R2)),
        stringsAsFactors = FALSE
      )
    }
  }
  skipped_df <- if (length(skipped)) do.call(rbind, skipped) else data.frame()
  safe_label <- gsub("[^A-Za-z0-9]+", "_", label)
  if (nrow(skipped_df)) {
    write_tsv(
      skipped_df,
      file.path(TABLES_DIR, paste0("180_", safe_label, "_skipped.tsv"))
    )
  }
  raw_df <- if (length(raw_results)) do.call(rbind, raw_results) else data.frame()
  write_tsv(
    raw_df,
    file.path(TABLES_DIR, paste0("180_", safe_label, "_iteration_deltas.tsv"))
  )
  if (length(results)) {
    do.call(rbind, results)
  } else {
    data.frame(
      analysis = character(),
      excluded = character(),
      delta_R2 = numeric(),
      n_iterations = integer(),
      stringsAsFactors = FALSE
    )
  }
}

loco <- run_leaveout("country", "Leave-one-country-out", 1000L)
