      isTRUE(all.equal(cthr, CLOUD_THRESHOLD))) next
  alt_class <- ifelse(global_prevalence >= pthr, "Prevalent", ifelse(global_prevalence >= cthr, "Shell", "Cloud"))
  alt_clr <- setNames(lapply(prevalence_levels, function(g) {
    clr_by_features(mat, rownames(mat)[alt_class == g], PSEUDOCOUNT)
  }), prevalence_levels)
  if (any(vapply(alt_clr, is.null, logical(1)))) next
  rr <- run_balanced_groups(
    alt_clr,
