  )
  dd <- paired_shell_delta(rr)
  analysis_label <- paste0(
    "Prevalence ", format(100 * pthr, trim = TRUE), "/",
    format(100 * cthr, trim = TRUE)
  )
  dd$analysis <- analysis_label
  dd$excluded <- paste0("Prevalent >= ", pthr, "; Cloud < ", cthr)
  threshold_results[[length(threshold_results) + 1L]] <- dd
  robust_raw[[paste0("threshold_", i)]] <- dd
}
