panel_b_summary <- merge(panel_b_summary, group_counts[, c("intersection_group", "n_KOs")], by.x = "group", by.y = "intersection_group", all.x = TRUE)
panel_b_summary$group <- factor(panel_b_summary$group, levels = rev(intersection_order[intersection_order %in% panel_b_summary$group]))
write_tsv(panel_b_summary, file.path(TABLES_DIR, "180_panel_b_summary.tsv"))

pB <- ggplot2::ggplot(panel_b_summary, ggplot2::aes(y = group, x = median)) +
  ggplot2::geom_segment(ggplot2::aes(x = lower, xend = upper, yend = group), linewidth = 0.8, colour = "#7F7F7F") +
  ggplot2::geom_point(ggplot2::aes(colour = as.character(group)), size = 2.8) +
  ggplot2::scale_colour_manual(
    values = c(
      "Prevalent" = "#B8122A",
      "Realm-core Shell" = "#F25353",
      "Peripheral Shell" = "#EF7A68",
      "Realm-core Cloud" = "#A9A9A9",
      "Peripheral Cloud" = "#777777"
    ),
    guide = "none"
  ) +
  ggplot2::labs(x = expression("Regional differentiation (" * R^2 * ")"), y = NULL) +
  theme_pub(9.2) +
  ggplot2::theme(axis.line.y = ggplot2::element_blank(), axis.ticks.y = ggplot2::element_blank())

# Panel c: paired balanced designs for Prevalent/Shell/Cloud.
prevalence_balanced$group <- factor(prevalence_balanced$group, levels = prevalence_levels)
prevalence_balanced$design <- factor(
  prevalence_balanced$design,
  levels = c(paste0(PRIMARY_N_REALMS, " x ", PRIMARY_N_LOCALITIES), paste0(SECONDARY_N_REALMS, " x ", SECONDARY_N_LOCALITIES)),
  labels = c(paste0(PRIMARY_N_REALMS, " realms x ", PRIMARY_N_LOCALITIES, " localities"), paste0(SECONDARY_N_REALMS, " realms x ", SECONDARY_N_LOCALITIES, " localities"))
)

pC <- ggplot2::ggplot(prevalence_balanced, ggplot2::aes(x = group, y = R2, fill = group)) +
  ggplot2::geom_violin(trim = TRUE, scale = "width", linewidth = 0.35, alpha = 0.9) +
  ggplot2::geom_boxplot(width = 0.16, outlier.shape = NA, fill = "white", linewidth = 0.35) +
  ggplot2::facet_wrap(~ design, nrow = 1L) +
  ggplot2::scale_fill_manual(values = COLORS_PREVALENCE, guide = "none") +
  ggplot2::labs(x = NULL, y = expression("Balanced PERMANOVA " * R^2)) +
  theme_pub(8.6) +
  ggplot2::theme(
    panel.spacing = grid::unit(0.45, "lines"),
    axis.text.x = ggplot2::element_text(size = 8.0),
    strip.text = ggplot2::element_text(size = 8.1, face = "bold")
  )

# Panel d: robustness of Shell vs the stronger of Prevalent and Cloud.
robust_order <- c(
  "Primary design",
  "Adjusted for KO annotation total",
  "Alternative design",
  "Equal-KO resampling",
  paste0("Detected in >= ", occurrence_thresholds[occurrence_thresholds > 1L], " samples"),
  if (nrow(threshold_results)) unique(threshold_results$analysis) else character(),
  "Leave-one-country-out",
  "Leave-one-study-out"
)
robust_summary <- robust_summary[robust_summary$analysis %in% robust_order, , drop = FALSE]
robust_summary$analysis <- factor(robust_summary$analysis, levels = rev(robust_order))

pD <- ggplot2::ggplot(robust_summary, ggplot2::aes(y = analysis, x = median)) +
  ggplot2::geom_vline(xintercept = 0, linetype = 2, linewidth = 0.45, colour = "#666666") +
  ggplot2::geom_segment(ggplot2::aes(x = lower, xend = upper, yend = analysis), linewidth = 0.75, colour = "#7F7F7F") +
  ggplot2::geom_point(size = 2.7, colour = "#B8122A") +
  ggplot2::labs(x = expression("Shell advantage in regional " * R^2), y = NULL) +
  theme_pub(8.8) +
  ggplot2::theme(axis.line.y = ggplot2::element_blank(), axis.ticks.y = ggplot2::element_blank())

